class TestRemoteSubtitlesUnit(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.TemporaryDirectory()
        self.work_dir = os.path.join(self.temp_dir.name, "work")
        os.makedirs(self.work_dir, exist_ok=True)

    def tearDown(self):
        self.temp_dir.cleanup()

    def test_parse_youtube_subtitles_categorization(self):
        info_dict = {
            "subtitles": {
                "en": [{"ext": "vtt", "url": "http://yt/en.vtt", "name": "English"}],
                "es": [{"ext": "vtt", "url": "http://yt/es.vtt", "name": "Spanish"}],
            },
            "automatic_captions": {
                "en": [{"ext": "vtt", "url": "http://yt/en-auto.vtt", "name": "English"}],
                "fr": [{"ext": "vtt", "url": "http://yt/fr-trans.vtt", "name": "French"}],
            },
        }
        tracks = parse_youtube_subtitles(info_dict)
        self.assertEqual(len(tracks), 4)
        manual_tracks = [t for t in tracks if t["type"] == "manual"]
        auto_tracks = [t for t in tracks if t["type"] == "autogenerated"]
        trans_tracks = [t for t in tracks if t["type"] == "translated"]

        self.assertEqual(len(manual_tracks), 2)
        self.assertEqual(len(auto_tracks), 1)
        self.assertEqual(auto_tracks[0]["label"], "English (autogenerated)")
        self.assertEqual(len(trans_tracks), 1)
        self.assertEqual(trans_tracks[0]["label"], "French (translated)")

    def test_parse_youtube_subtitles_explicit_audio_language(self):
        info_dict = {
            "language": "es",
            "subtitles": {
                "en": [{"ext": "vtt", "url": "http://yt/en.vtt", "name": "English"}],
            },
            "automatic_captions": {
                "es": [{"ext": "vtt", "url": "http://yt/es-auto.vtt", "name": "Spanish"}],
                "en": [{"ext": "vtt", "url": "http://yt/en-trans.vtt", "name": "English"}],
            },
        }
        tracks = parse_youtube_subtitles(info_dict)
        self.assertEqual(len(tracks), 3)
        auto_tracks = [t for t in tracks if t["type"] == "autogenerated"]
        trans_tracks = [t for t in tracks if t["type"] == "translated"]
        self.assertEqual(len(auto_tracks), 1)
        self.assertEqual(auto_tracks[0]["language"], "spa")
        self.assertEqual(auto_tracks[0]["label"], "Spanish (autogenerated)")
        self.assertEqual(len(trans_tracks), 1)
        self.assertEqual(trans_tracks[0]["language"], "eng")
        self.assertEqual(trans_tracks[0]["label"], "English (translated)")

    def test_parse_youtube_subtitles_empty_and_missing_urls(self):
        self.assertEqual(parse_youtube_subtitles({}), [])
        info_dict = {
            "subtitles": {
                "en": [{"ext": "vtt", "name": "No URL"}],
            },
            "automatic_captions": {
                "es": [{"ext": "srv3", "name": "No URL either"}],
            },
        }
        self.assertEqual(parse_youtube_subtitles(info_dict), [])

    def test_parse_youtube_subtitles_hyphenated_language_codes(self):
        info_dict = {
            "subtitles": {
                "en-US": [{"ext": "vtt", "url": "http://yt/en-us.vtt", "name": "English (US)"}],
                "pt-BR": [{"ext": "vtt", "url": "http://yt/pt-br.vtt", "name": "Portuguese (Brazil)"}],
                "es-419": [{"ext": "vtt", "url": "http://yt/es-419.vtt", "name": "Spanish (Latin America)"}],
            },
        }
        tracks = parse_youtube_subtitles(info_dict)
        self.assertEqual(len(tracks), 3)
        by_lang = {t["language"]: t for t in tracks}
        self.assertIn("eng", by_lang)
        self.assertIn("por", by_lang)
        self.assertIn("spa", by_lang)
        self.assertNotIn("en-", by_lang)
        self.assertNotIn("pt-", by_lang)
        self.assertNotIn("es-", by_lang)

