        with open(out_path, "r", encoding="utf-8") as f:
            content = f.read()
        self.assertTrue(content.startswith("WEBVTT"))
        self.assertIn("00:00:02.000 --> 00:00:05.000", content)
        self.assertIn("From Zip", content)

